import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  counters: defineTable({
    runId: v.string(),
    count: v.number(),
  }).index("by_runId", ["runId"]),
});

import { mutation, query } from "convex/server";
import { v } from "convex/values";

export const get = query({
  args: { runId: v.string() },
  handler: async (ctx, { runId }) => {
    return await ctx.db
      .query("counters")
      .withIndex("by_runId", (q) => q.eq("runId", runId))
      .unique();
  },
});

export const increment = mutation({
  args: { runId: v.string() },
  handler: async (ctx, { runId }) => {
    const existing = await ctx.db
      .query("counters")
      .withIndex("by_runId", (q) => q.eq("runId", runId))
      .unique();

    if (existing) {
      const nextCount = existing.count + 1;
      await ctx.db.patch(existing._id, { count: nextCount });
      return nextCount;
    }

    await ctx.db.insert("counters", { runId, count: 1 });
    return 1;
  },
});

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { ConvexProvider, ConvexReactClient } from "convex/react";
import App from "./App.jsx";
import "./index.css";

const convexUrl = import.meta.env.VITE_CONVEX_URL;
const convex = new ConvexReactClient(convexUrl);

createRoot(document.getElementById("root")).render(
  <StrictMode>
    <ConvexProvider client={convex}>
      <App />
    </ConvexProvider>
  </StrictMode>
);

import { useMutation, useQuery } from "convex/react";
import { api } from "../convex/_generated/api";
import "./App.css";

function App() {
  const runId = import.meta.env.VITE_RUN_ID;
  const counter = useQuery(api.counters.get, runId ? { runId } : "skip");
  const increment = useMutation(api.counters.increment);

  const handleIncrement = async () => {
    if (!runId) {
      return;
    }
    await increment({ runId });
  };

  if (!runId) {
    return (
      <div className="app">
        <h1>Collaborative Counter</h1>
        <p className="status">
          Missing <code>VITE_RUN_ID</code>. Start the app with
          <code>VITE_RUN_ID=$ZEALT_RUN_ID</code> so each run is isolated.
        </p>
      </div>
    );
  }

  const countValue = counter ? counter.count : 0;

  return (
    <div className="app">
      <h1>Collaborative Counter</h1>
      <p className="status">Run ID: {runId}</p>
      <div className="counter-card">
        <p className="count">{counter === undefined ? "Loading..." : countValue}</p>
        <button type="button" onClick={handleIncrement}>
          Increment
        </button>
      </div>
    </div>
  );
}

export default App;

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  font-family: "Inter", system-ui, sans-serif;
  padding: 24px;
  background: #f8fafc;
  color: #0f172a;
}

.counter-card {
  background: white;
  padding: 24px 32px;
  border-radius: 16px;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.1);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.count {
  font-size: 48px;
  font-weight: 700;
  margin: 0;
}

.status {
  margin: 0;
  font-size: 14px;
  color: #475569;
}

button {
  background: #2563eb;
  color: white;
  border: none;
  border-radius: 999px;
  padding: 10px 24px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.1s ease, box-shadow 0.1s ease;
}

button:hover {
  box-shadow: 0 8px 20px rgba(37, 99, 235, 0.3);
  transform: translateY(-1px);
}

code {
  margin-left: 8px;
}

